  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.controller.*;
  7	import com.pousadamarealta.database.DatabaseInitializer;
  8	import com.pousadamarealta.dto.ErrorResponse;
  9	import com.pousadamarealta.exception.*;
 10	import com.pousadamarealta.repository.MessageRepository;
 11	import com.pousadamarealta.repository.ReservationRepository;
 12	import com.pousadamarealta.service.*;
 13	import com.zaxxer.hikari.HikariConfig;
 14	import com.zaxxer.hikari.HikariDataSource;
 15	import io.javalin.Javalin;
 16	import io.javalin.http.HttpStatus;
 17	import io.javalin.json.JavalinJackson;
 18	
 19	import javax.sql.DataSource;
 20	
 21	public class Main {
 22	    public static void main(String[] args) {
 23	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 24	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 25	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 26	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 27	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 28	
 29	        DataSource dataSource = createDataSource(dbUrl, dbUser, dbPassword);
 30	        DatabaseInitializer.initialize(dataSource);
 31	
 32	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 33	        MessageRepository messageRepository = new MessageRepository(dataSource);
 34	
 35	        RoomService roomService = new RoomService();
 36	        PricingService pricingService = new PricingService();
 37	        MessageService messageService = new MessageService(messageRepository, testMode);
 38	        ReservationService reservationService = new ReservationService(
 39	            reservationRepository, roomService, pricingService, messageService);
 40	        ReportService reportService = new ReportService(reservationService, roomService);
 41	
 42	        RoomController roomController = new RoomController(roomService);
 43	        ReservationController reservationController = new ReservationController(reservationService, roomService);
 44	        MessageController messageController = new MessageController(messageService);
 45	        ReportController reportController = new ReportController(reportService);
 46	
 47	        ObjectMapper objectMapper = new ObjectMapper();
 48	        objectMapper.registerModule(new JavaTimeModule());
 49	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 50	
 51	        Javalin app = Javalin.create(config -> {
 52	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 53	        }).start(port);
 54	
 55	        app.get("/rooms", roomController::getRooms);
 56	        app.post("/reservations", reservationController::createReservation);
 57	        app.get("/reservations/{id}", reservationController::getReservation);
 58	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 59	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 60	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 61	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 62	        app.get("/reservations/{id}/document", reservationController::getDocument);
 63	        app.get("/messages", messageController::getMessages);
 64	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 65	        app.get("/reports/revenue", reportController::getRevenueReport);
 66	
 67	        app.exception(InvalidRequestException.class, (e, ctx) -> {
 68	            ctx.status(HttpStatus.BAD_REQUEST).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 69	        });
 70	
 71	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
 72	            ctx.status(HttpStatus.NOT_FOUND).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
 73	        });
 74	
 75	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
 76	            ctx.status(HttpStatus.NOT_FOUND).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
 77	        });
 78	
 79	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
 80	            ctx.status(HttpStatus.CONFLICT).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
 81	        });
 82	
 83	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
 84	            ctx.status(HttpStatus.CONFLICT).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
 85	        });
 86	
 87	        app.exception(CapacityExceededException.class, (e, ctx) -> {
 88	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
 89	        });
 90	
 91	        app.exception(Exception.class, (e, ctx) -> {
 92	            e.printStackTrace();
 93	            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR).json(
 94	                new ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred"));
 95	        });
 96	    }
 97	
 98	    private static DataSource createDataSource(String url, String user, String password) {
 99	        HikariConfig config = new HikariConfig();
100	        config.setJdbcUrl(url);
101	        config.setUsername(user);
102	        config.setPassword(password);
103	        config.setMaximumPoolSize(10);
104	        return new HikariDataSource(config);
105	    }
106	}
