133	import com.pousadamarealta.exception.InvalidRequestException;
134	import com.pousadamarealta.service.ReportService;
135	import io.javalin.http.Context;
136	
137	import java.time.LocalDate;
138	import java.time.YearMonth;
139	import java.time.format.DateTimeFormatter;
140	import java.time.format.DateTimeParseException;
141	
142	public class ReportController {
143	    private final ReportService reportService;
144	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE;
145	    private static final DateTimeFormatter MONTH_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM");
146	
147	    public ReportController(ReportService reportService) {
148	        this.reportService = reportService;
149	    }
150	
151	    public void getOccupancyReport(Context ctx) {
152	        String dateParam = ctx.queryParam("date");
153	        if (dateParam == null || dateParam.isBlank()) {
154	            throw new InvalidRequestException("Date parameter is required");
155	        }
156	
157	        LocalDate date;
158	        try {
159	            date = LocalDate.parse(dateParam, DATE_FORMATTER);
160	        } catch (DateTimeParseException e) {
161	            throw new InvalidRequestException("Invalid date format. Expected: yyyy-MM-dd");
162	        }
163	
164	        String csv = reportService.generateOccupancyReport(date);
165	        ctx.contentType("text/csv; charset=utf-8").result(csv);
166	    }
167	
168	    public void getRevenueReport(Context ctx) {
169	        String monthParam = ctx.queryParam("month");
170	        if (monthParam == null || monthParam.isBlank()) {
171	            throw new InvalidRequestException("Month parameter is required");
172	        }
173	
174	        YearMonth yearMonth;
175	        try {
176	            yearMonth = YearMonth.parse(monthParam, MONTH_FORMATTER);
177	        } catch (DateTimeParseException e) {
178	            throw new InvalidRequestException("Invalid month format. Expected: yyyy-MM");
179	        }
180	
181	        String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
182	        ctx.contentType("text/csv; charset=utf-8").result(csv);
183	    }
184	}
185	package com.pousadamarealta.controller;
