187	import com.pousadamarealta.dto.CreateReservationRequest;
188	import com.pousadamarealta.dto.DocumentDTO;
189	import com.pousadamarealta.dto.ReservationDTO;
190	import com.pousadamarealta.exception.InvalidRequestException;
191	import com.pousadamarealta.mapper.ModelMapper;
192	import com.pousadamarealta.model.RatePlan;
193	import com.pousadamarealta.model.Reservation;
194	import com.pousadamarealta.service.ReservationService;
195	import com.pousadamarealta.service.RoomService;
196	import io.javalin.http.Context;
197	
198	import java.time.LocalDate;
199	import java.time.format.DateTimeFormatter;
200	import java.time.format.DateTimeParseException;
201	
202	public class ReservationController {
203	    private final ReservationService reservationService;
204	    private final RoomService roomService;
205	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE;
206	
207	    public ReservationController(ReservationService reservationService, RoomService roomService) {
208	        this.reservationService = reservationService;
209	        this.roomService = roomService;
210	    }
211	
212	    public void createReservation(Context ctx) {
213	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
214	
215	        validateRequest(request);
216	
217	        LocalDate checkIn = parseDate(request.getCheckIn());
218	        LocalDate checkOut = parseDate(request.getCheckOut());
219	
220	        if (!checkOut.isAfter(checkIn)) {
221	            throw new InvalidRequestException("Check-out date must be after check-in date");
222	        }
223	
224	        if (request.getGuests() < 1) {
225	            throw new InvalidRequestException("Number of guests must be at least 1");
226	        }
227	
228	        RatePlan ratePlan;
229	        try {
230	            ratePlan = RatePlan.valueOf(request.getRatePlan());
231	        } catch (IllegalArgumentException e) {
232	            throw new InvalidRequestException("Invalid rate plan: " + request.getRatePlan());
233	        }
234	
235	        Reservation reservation = reservationService.createReservation(
236	            request.getRoomNumber(),
237	            request.getGuestName(),
238	            request.getGuestEmail(),
239	            request.getGuestCpf(),
240	            checkIn,
241	            checkOut,
242	            request.getGuests(),
243	            ratePlan
244	        );
245	
246	        ctx.status(201).json(ModelMapper.toDTO(reservation));
247	    }
248	
249	    public void getReservation(Context ctx) {
250	        Long id = ctx.pathParamAsClass("id", Long.class).get();
251	        Reservation reservation = reservationService.findById(id);
252	        ctx.json(ModelMapper.toDTO(reservation));
253	    }
254	
255	    public void confirmReservation(Context ctx) {
256	        Long id = ctx.pathParamAsClass("id", Long.class).get();
257	        Reservation reservation = reservationService.confirmReservation(id);
258	        ctx.json(ModelMapper.toDTO(reservation));
259	    }
260	
261	    public void cancelReservation(Context ctx) {
262	        Long id = ctx.pathParamAsClass("id", Long.class).get();
263	        Reservation reservation = reservationService.cancelReservation(id);
264	        ctx.json(ModelMapper.toDTO(reservation));
265	    }
266	
267	    public void checkIn(Context ctx) {
268	        Long id = ctx.pathParamAsClass("id", Long.class).get();
269	        Reservation reservation = reservationService.checkIn(id);
270	        ctx.json(ModelMapper.toDTO(reservation));
271	    }
272	
273	    public void checkOut(Context ctx) {
274	        Long id = ctx.pathParamAsClass("id", Long.class).get();
275	        Reservation reservation = reservationService.checkOut(id);
276	        String roomType = roomService.findByNumber(reservation.getRoomNumber()).get().getType().name();
277	        DocumentDTO document = ModelMapper.toDocumentDTO(reservation, roomType);
278	        ctx.json(document);
279	    }
280	
281	    public void getDocument(Context ctx) {
282	        Long id = ctx.pathParamAsClass("id", Long.class).get();
283	        Reservation reservation = reservationService.findById(id);
284	        String roomType = roomService.findByNumber(reservation.getRoomNumber()).get().getType().name();
285	        DocumentDTO document = ModelMapper.toDocumentDTO(reservation, roomType);
286	        ctx.json(document);
287	    }
288	
289	    private void validateRequest(CreateReservationRequest request) {
290	        if (request.getRoomNumber() == null || request.getRoomNumber().isBlank()) {
291	            throw new InvalidRequestException("Room number is required");
292	        }
293	        if (request.getGuestName() == null || request.getGuestName().isBlank()) {
294	            throw new InvalidRequestException("Guest name is required");
295	        }
296	        if (request.getGuestEmail() == null || request.getGuestEmail().isBlank()) {
297	            throw new InvalidRequestException("Guest email is required");
298	        }
299	        if (request.getGuestCpf() == null || request.getGuestCpf().isBlank()) {
300	            throw new InvalidRequestException("Guest CPF is required");
301	        }
302	        if (request.getCheckIn() == null || request.getCheckIn().isBlank()) {
303	            throw new InvalidRequestException("Check-in date is required");
304	        }
305	        if (request.getCheckOut() == null || request.getCheckOut().isBlank()) {
306	            throw new InvalidRequestException("Check-out date is required");
307	        }
308	        if (request.getRatePlan() == null || request.getRatePlan().isBlank()) {
309	            throw new InvalidRequestException("Rate plan is required");
310	        }
311	    }
312	
313	    private LocalDate parseDate(String dateString) {
314	        try {
315	            return LocalDate.parse(dateString, DATE_FORMATTER);
316	        } catch (DateTimeParseException e) {
317	            throw new InvalidRequestException("Invalid date format. Expected: yyyy-MM-dd");
318	        }
319	    }
320	}
