 69	package com.pousadamarealta.service;
 70	
 71	import com.pousadamarealta.model.RatePlan;
 72	
 73	import java.math.BigDecimal;
 74	import java.math.RoundingMode;
 75	import java.time.LocalDate;
 76	
 77	public class PricingService {
 78	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 79	    private static final int SCALE = 2;
 80	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 81	
 82	    public boolean isHighSeason(LocalDate date) {
 83	        int month = date.getMonthValue();
 84	        int day = date.getDayOfMonth();
 85	
 86	        if (month == 7) {
 87	            return true;
 88	        }
 89	
 90	        if (month == 12 && day >= 15) {
 91	            return true;
 92	        }
 93	
 94	        if (month == 1 || month == 2) {
 95	            return true;
 96	        }
 97	
 98	        return false;
 99	    }
100	
101	    public BigDecimal calculateNightlyRate(double baseRate, LocalDate date) {
102	        BigDecimal rate = BigDecimal.valueOf(baseRate);
103	
104	        if (isHighSeason(date)) {
105	            rate = rate.multiply(HIGH_SEASON_MULTIPLIER);
106	        }
107	
108	        return rate.setScale(SCALE, ROUNDING_MODE);
109	    }
110	
111	    public BigDecimal calculateSubtotal(double baseRate, LocalDate checkIn, LocalDate checkOut) {
112	        BigDecimal subtotal = BigDecimal.ZERO;
113	        LocalDate currentDate = checkIn;
114	
115	        while (currentDate.isBefore(checkOut)) {
116	            BigDecimal nightlyRate = calculateNightlyRate(baseRate, currentDate);
117	            subtotal = subtotal.add(nightlyRate);
118	            currentDate = currentDate.plusDays(1);
119	        }
120	
121	        return subtotal.setScale(SCALE, ROUNDING_MODE);
122	    }
123	
124	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
125	        double discountRate = ratePlan.getDiscountRate();
126	        if (discountRate == 0.0) {
127	            return BigDecimal.ZERO;
128	        }
129	
130	        BigDecimal discount = subtotal.multiply(BigDecimal.valueOf(discountRate));
131	        return discount.setScale(SCALE, ROUNDING_MODE);
132	    }
133	
134	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
135	        return subtotal.subtract(discount).setScale(SCALE, ROUNDING_MODE);
136	    }
137	}
