153	    public ReportService(ReservationService reservationService, RoomService roomService) {
154	        this.reservationService = reservationService;
155	        this.roomService = roomService;
156	    }
157	
158	    public String generateOccupancyReport(LocalDate date) {
159	        StringBuilder csv = new StringBuilder();
160	        csv.append("room,type,reservation,check_in,check_out\n");
161	
162	        List<Room> allRooms = roomService.getAllRooms();
163	        int occupiedCount = 0;
164	
165	        for (Room room : allRooms) {
166	            List<Reservation> occupying = reservationService.findOccupyingRoom(room.getNumber(), date);
167	
168	            if (!occupying.isEmpty()) {
169	                Reservation reservation = occupying.get(0);
170	                csv.append(String.format("%s,%s,%d,%s,%s\n",
171	                    room.getNumber(),
172	                    room.getType().name(),
173	                    reservation.getId(),
174	                    formatDate(reservation.getCheckIn()),
175	                    formatDate(reservation.getCheckOut())));
176	                occupiedCount++;
177	            }
178	        }
179	
180	        csv.append(String.format("total,%d/%d\n", occupiedCount, allRooms.size()));
181	
182	        return csv.toString();
183	    }
184	
185	    public String generateRevenueReport(int year, int month) {
186	        StringBuilder csv = new StringBuilder();
187	        csv.append("reservation,room,check_in,check_out,status,amount\n");
188	
189	        List<Reservation> reservations = reservationService.findByCheckInMonth(year, month);
190	        BigDecimal totalRevenue = BigDecimal.ZERO;
191	
192	        for (Reservation reservation : reservations) {
193	            BigDecimal revenue = calculateRevenue(reservation);
194	
195	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
196	                csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
197	                    reservation.getId(),
198	                    reservation.getRoomNumber(),
199	                    formatDate(reservation.getCheckIn()),
200	                    formatDate(reservation.getCheckOut()),
201	                    reservation.getStatus().name(),
202	                    formatAmount(revenue)));
203	
204	                totalRevenue = totalRevenue.add(revenue);
205	            }
206	        }
207	
208	        csv.append(String.format("total,%s\n", formatAmount(totalRevenue)));
209	
210	        return csv.toString();
211	    }
212	
213	    private BigDecimal calculateRevenue(Reservation reservation) {
214	        BigDecimal paid = reservation.getAmountPaid();
215	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
216	        return paid.subtract(refunded);
217	    }
218	
219	    private String formatDate(LocalDate date) {
220	        return date.format(DateTimeFormatter.ISO_LOCAL_DATE);
221	    }
222	
223	    private String formatAmount(BigDecimal amount) {
224	        return amount.toString();
225	    }
226	}
