232	import com.pousadamarealta.repository.ReservationRepository;
233	
234	import java.math.BigDecimal;
235	import java.time.LocalDate;
236	import java.time.format.DateTimeFormatter;
237	import java.time.temporal.ChronoUnit;
238	import java.util.List;
239	import java.util.Optional;
240	
241	public class ReservationService {
242	    private final ReservationRepository reservationRepository;
243	    private final RoomService roomService;
244	    private final PricingService pricingService;
245	    private final MessageService messageService;
246	
247	    public ReservationService(ReservationRepository reservationRepository, RoomService roomService,
248	                              PricingService pricingService, MessageService messageService) {
249	        this.reservationRepository = reservationRepository;
250	        this.roomService = roomService;
251	        this.pricingService = pricingService;
252	        this.messageService = messageService;
253	    }
254	
255	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
256	                                         LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
257	        Room room = roomService.findByNumber(roomNumber)
258	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
259	
260	        validateReservation(room, checkIn, checkOut, guests, null);
261	
262	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
263	        BigDecimal subtotal = pricingService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
264	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
265	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
266	
267	        Reservation reservation = new Reservation();
268	        reservation.setRoomNumber(roomNumber);
269	        reservation.setGuestName(guestName);
270	        reservation.setGuestEmail(guestEmail);
271	        reservation.setGuestCpf(guestCpf);
272	        reservation.setCheckIn(checkIn);
273	        reservation.setCheckOut(checkOut);
274	        reservation.setGuests(guests);
275	        reservation.setRatePlan(ratePlan);
276	        reservation.setNights(nights);
277	        reservation.setSubtotal(subtotal);
278	        reservation.setDiscount(discount);
279	        reservation.setTotal(total);
280	        reservation.setStatus(ReservationStatus.PENDING);
281	        reservation.setAmountPaid(BigDecimal.ZERO);
282	        reservation.setRefund(null);
283	
284	        return reservationRepository.save(reservation);
285	    }
286	
287	    public Reservation confirmReservation(Long id) {
288	        Reservation reservation = findById(id);
289	
290	        if (reservation.getStatus() != ReservationStatus.PENDING) {
291	            throw new OperationNotAllowedException("Reservation cannot be confirmed in status: " + reservation.getStatus());
292	        }
293	
294	        reservation.setStatus(ReservationStatus.CONFIRMED);
295	        reservation.setAmountPaid(reservation.getTotal());
296	        reservationRepository.update(reservation);
297	
298	        sendConfirmationEmail(reservation);
299	
300	        return reservation;
301	    }
302	
303	    public Reservation cancelReservation(Long id) {
304	        Reservation reservation = findById(id);
305	
306	        if (reservation.getStatus() != ReservationStatus.PENDING && reservation.getStatus() != ReservationStatus.CONFIRMED) {
307	            throw new OperationNotAllowedException("Reservation cannot be cancelled in status: " + reservation.getStatus());
308	        }
309	
310	        reservation.setStatus(ReservationStatus.CANCELLED);
311	
312	        BigDecimal refund = BigDecimal.ZERO;
313	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
314	            refund = reservation.getAmountPaid();
315	        }
316	        reservation.setRefund(refund);
317	
318	        reservationRepository.update(reservation);
319	
320	        return reservation;
321	    }
322	
323	    public Reservation checkIn(Long id) {
324	        Reservation reservation = findById(id);
325	
326	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
327	            throw new OperationNotAllowedException("Reservation cannot be checked in from status: " + reservation.getStatus());
328	        }
329	
330	        reservation.setStatus(ReservationStatus.CHECKED_IN);
331	        reservationRepository.update(reservation);
332	
333	        return reservation;
334	    }
335	
336	    public Reservation checkOut(Long id) {
337	        Reservation reservation = findById(id);
338	
339	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
340	            throw new OperationNotAllowedException("Reservation cannot be checked out from status: " + reservation.getStatus());
341	        }
342	
343	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
344	        reservationRepository.update(reservation);
345	
346	        return reservation;
347	    }
348	
349	    public Reservation findById(Long id) {
350	        return reservationRepository.findById(id)
351	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found: " + id));
352	    }
353	
354	    public String generateDocument(Reservation reservation) {
355	        if (reservation.getStatus() == ReservationStatus.PENDING || reservation.getStatus() == ReservationStatus.CANCELLED) {
356	            throw new OperationNotAllowedException("Cannot generate document for reservation in status: " + reservation.getStatus());
357	        }
358	
359	        Room room = roomService.findByNumber(reservation.getRoomNumber()).orElseThrow();
360	        return buildReceipt(reservation, room);
361	    }
362	
363	    private void sendConfirmationEmail(Reservation reservation) {
364	        Room room = roomService.findByNumber(reservation.getRoomNumber()).orElseThrow();
365	        String receipt = buildReceipt(reservation, room);
366	
367	        String subject = "Reserva confirmada - Pousada Maré Alta";
368	        String body = String.format("Olá, %s!\n\nSua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n%s\n\nA entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!",
369	            reservation.getGuestName(), receipt);
370	
371	        OutgoingMessage message = new OutgoingMessage(MessageChannel.EMAIL, reservation.getGuestEmail(), subject, body);
372	        messageService.send(message);
373	    }
374	
375	    private String buildReceipt(Reservation reservation, Room room) {
376	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
377	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
378	
379	        StringBuilder receipt = new StringBuilder();
380	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
381	        receipt.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
382	        receipt.append(String.format("Quarto: %s (%s)\n", reservation.getRoomNumber(), room.getType().name()));
383	        receipt.append(String.format("Entrada: %s | Saída: %s | %s\n",
384	            reservation.getCheckIn().format(dateFormatter),
385	            reservation.getCheckOut().format(dateFormatter),
386	            nightsText));
387	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
388	
389	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
390	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
391	        }
392	
393	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
394	
395	        return receipt.toString();
396	    }
397	
398	    private String formatCpf(String cpf) {
399	        if (cpf.length() == 11) {
400	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
401	        }
402	        return cpf;
403	    }
404	
405	    private String formatMoney(BigDecimal amount) {
406	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
407	    }
408	
409	    private void validateReservation(Room room, LocalDate checkIn, LocalDate checkOut, int guests, Long excludeReservationId) {
410	        if (guests > room.getCapacity()) {
411	            throw new CapacityExceededException("Room capacity exceeded. Max: " + room.getCapacity() + ", requested: " + guests);
412	        }
413	
414	        List<Reservation> conflicts = reservationRepository.findConflictingReservations(
415	            room.getNumber(), checkIn, checkOut, excludeReservationId);
416	
417	        if (!conflicts.isEmpty()) {
418	            throw new RoomUnavailableException("Room is not available for the selected dates");
419	        }
420	    }
421	
422	    public List<Reservation> findByCheckInMonth(int year, int month) {
423	        return reservationRepository.findByCheckInMonth(year, month);
424	    }
425	
426	    public List<Reservation> findOccupyingRoom(String roomNumber, LocalDate date) {
427	        return reservationRepository.findOccupyingRoom(roomNumber, date);
428	    }
429	}
