     1	package com.pousadamarealta.messaging.rules;
     2	
     3	import com.pousadamarealta.messaging.MessageRule;
     4	import com.pousadamarealta.messaging.OutgoingMessage;
     5	import com.pousadamarealta.messaging.ProcessingResult;
     6	
     7	public class EmailValidationRule implements MessageRule {
     8	
     9	    @Override
    10	    public ProcessingResult process(OutgoingMessage message) {
    11	        if (!isValidEmail(message.getTo())) {
    12	            return ProcessingResult.block(message);
    13	        }
    14	        return ProcessingResult.allow(message);
    15	    }
    16	
    17	    private boolean isValidEmail(String email) {
    18	        if (email == null || email.isEmpty()) {
    19	            return false;
    20	        }
    21	
    22	        int atCount = 0;
    23	        int atPosition = -1;
    24	        for (int i = 0; i < email.length(); i++) {
    25	            if (email.charAt(i) == '@') {
    26	                atCount++;
    27	                atPosition = i;
    28	            }
    29	        }
    30	
    31	        if (atCount != 1) {
    32	            return false;
    33	        }
    34	
    35	        if (atPosition == 0 || atPosition == email.length() - 1) {
    36	            return false;
    37	        }
    38	
    39	        String domain = email.substring(atPosition + 1);
    40	
    41	        return domain.contains(".");
    42	    }
    43	}
